+	"./modules/caddypki"
+)
+
+func main() {
+	// Test default values
+	pki := &caddypki.PKI{}
+	
+	fmt.Printf("Default maintenance interval: %v\n", pki.getMaintenanceInterval())
+	fmt.Printf("Default renewal window ratio: %v\n", pki.getRenewalWindowRatio())
